use rk3588_boot_support::Mmio32;use crate::stage14::{DdrSequenceError,DdrTrainer};use crate::stage15::{EarlyDdrReport,EarlyDdrRuntime};use crate::stage16::{DdrEntryHooks,DdrInitEntryError,DdrInitEntryReport};
pub const DDR_BOOT_CODE_ADDR:u64=0xFF00_0010;pub const DDR_PREP_FIXUP_ADDR:u64=0xFD5F_8098;pub const DDR_PREP_FIXUP_VALUE:u32=0xFF00_5500;pub const DDR_PREP_CLEAR_ADDRS:[u64;4]=[0xFE01_00F0,0xFE01_00F4,0xFE01_00F8,0xFE01_00FC];
pub fn run_pre_ddr_hw_init_exact<I:Mmio32>(io:&mut I){if io.read32(DDR_BOOT_CODE_ADDR)!=5{io.write32(DDR_PREP_FIXUP_ADDR,DDR_PREP_FIXUP_VALUE)}for a in DDR_PREP_CLEAR_ADDRS{io.write32(a,0)}}
pub fn run_ddr_init_entry_stage17<I:EarlyDdrRuntime+Mmio32,T:DdrTrainer,H:DdrEntryHooks>(io:&mut I,trainer:&mut T,hooks:&mut H,uart_base:u64,baud:u32)->Result<DdrInitEntryReport,DdrInitEntryError<H::Error,T::Error>>{if let Err(e)=hooks.preflight(){hooks.emit_error();hooks.invalidate_icache_all();return Err(DdrInitEntryError::Hook(e))}run_pre_ddr_hw_init_exact(io);let timer_reinitialized=!hooks.timer_already_ready();if timer_reinitialized{crate::stage13::init_arch_timer(io)}crate::stage12::init_debug_uart(io,uart_base,baud);hooks.emit_banner();let probe_byte=match crate::stage14::run_ddr_probe_and_train(io,trainer){Ok(v)=>v,Err(DdrSequenceError::Training(e))=>{hooks.emit_error();hooks.invalidate_icache_all();return Err(DdrInitEntryError::Training(e))}};if let Err(e)=hooks.post_training_check(){hooks.emit_error();hooks.invalidate_icache_all();return Err(DdrInitEntryError::Hook(e))}hooks.invalidate_icache_all();Ok(DdrInitEntryReport{early:EarlyDdrReport{probe_byte,uart_base,baud},timer_reinitialized})}
#[cfg(test)]mod tests{use super::*;use rk3588_boot_support::{BarrierOps,DelayUs,Mmio8};use crate::stage13::ArchTimerIo;struct I{boot:u32,fix:u32,clears:u8,freq:u32,status:u32,probe:u8}impl Mmio32 for I{fn read32(&mut self,a:u64)->u32{match a{DDR_BOOT_CODE_ADDR=>self.boot,x if x==crate::stage14::DDR_PROBE_BASE+0x84=>self.status,_=>0}}fn write32(&mut self,a:u64,v:u32){if a==DDR_PREP_FIXUP_ADDR{self.fix=v}else if DDR_PREP_CLEAR_ADDRS.contains(&a){self.clears+=1}else if a==crate::stage14::DDR_PROBE_BASE+0x84&&v==15{self.status=3}}}impl Mmio8 for I{fn read8(&mut self,a:u64)->u8{if a==crate::stage14::DDR_PROBE_BASE+0x22{self.probe}else{0}}}impl DelayUs for I{fn delay_us(&mut self,_:u32){}}impl BarrierOps for I{fn dsb(&mut self){}fn isb(&mut self){}}impl ArchTimerIo for I{fn write_cntfrq_el0(&mut self,h:u32){self.freq=h}}impl crate::stage12::DebugUartIo for I{fn write32(&mut self,_:u64,_:u32){}}struct T;impl DdrTrainer for T{type Error=();fn train(&mut self,_:u8)->Result<(),()>{Ok(())}}struct H;impl DdrEntryHooks for H{type Error=();fn preflight(&mut self)->Result<(),()>{Ok(())}fn timer_already_ready(&mut self)->bool{false}fn emit_banner(&mut self){}fn post_training_check(&mut self)->Result<(),()>{Ok(())}fn emit_error(&mut self){}fn invalidate_icache_all(&mut self){}}#[test]fn exact_prefix(){let mut i=I{boot:0,fix:0,clears:0,freq:0,status:0,probe:0x5a};run_pre_ddr_hw_init_exact(&mut i);assert_eq!(i.fix,DDR_PREP_FIXUP_VALUE);assert_eq!(i.clears,4);}#[test]fn entry(){let mut i=I{boot:5,fix:0,clears:0,freq:0,status:0,probe:0x5a};let(mut t,mut h)=(T,H);let r=run_ddr_init_entry_stage17(&mut i,&mut t,&mut h,0xFE66_0000,115200).unwrap();assert_eq!(r.early.probe_byte,0x5a);assert_eq!(i.clears,4);assert_eq!(i.freq,24_000_000);}}
